from moler.device import DeviceFactory
from taf.rfrl.utilities.tl_config import load_moler_configuration_from_tl
from taf.rfrl.utilities.general import get_timestamp
from taf.rfrl.utilities.logger.custom_logger import log_info_to_console


class CustomEntryNotDetected(Exception):
    pass


class ObserverAlreadyExist(Exception):
    pass


class ObserverNotStarted(Exception):
    pass


class GenericObserver:
    """
    EXAMPLE USAGE:
    from taf.rfrl.bts.devices.generic_bts import GenericBts
    from taf.rfrl.utilities.observers.generic_observer import GenericObserver

    class SFPSyslogObserver:
        def __init__(self, bts_type='GNB'):
            self.custom_entry_observer = GenericObserver(device_name=GenericBts().syslog_alias.format(0, 0))
            self.syslog_params = {"detect_patterns": [r"SFP module initialization completed"],
                                  "match": 'all',
                                  "till_occurs_times": 1}

        def start_sfp_observer(self):
            self.custom_entry_observer.start_custom_entry_observer(event_params=self.syslog_params)

        def verify_sfp_observer_results(self):
            self.custom_entry_observer.verify_custom_entry_occurred()
    """
    OBSERVERS = {}

    def __init__(self, device_name, observer_name=None):
        """
        Constructor of GenericObserver class.
        :param device_name: alias of device to observe, e.g. GenericBts().syslog_alias.format(gnb_id, du_id)
        :param observer_name: name of observer
        """
        self.device_name = device_name
        self.observer_name = observer_name if observer_name else self.__class__.__name__
        self._custom_entry_occurred = False

    @property
    def observer(self):
        try:
            return self.OBSERVERS[self.observer_name][self.device_name]
        except KeyError:
            return None

    @observer.setter
    def observer(self, value):
        if self.observer_name not in self.OBSERVERS:
            self.OBSERVERS[self.observer_name] = {}
        self.OBSERVERS[self.observer_name][self.device_name] = value

    @load_moler_configuration_from_tl()
    def start_custom_entry_observer(self, event_params, timeout=None):
        """
        Start custom entry observer on BTS
        :param event_params: pattern parameters to detect by observer,
                             e.g. {"detect_patterns": ["custom_patter"],
                                   "match": 'all',
                                   "till_occurs_times": 1}
        :param timeout: timeout for running observer
        """
        if self.observer is not None:
            raise ObserverAlreadyExist(f"Observer with name '{self.observer_name}' already exist. "
                                       f"Verify previous observer results or use different observer name.")

        sys_device = DeviceFactory.get_device(name=self.device_name)
        self.observer = sys_device.get_event(
            event_name="wait4",
            event_params=event_params
        )
        self.observer.add_event_occurred_callback(
            callback=self._custom_entry_callback,
            callback_params={'event_pattern': event_params["detect_patterns"]}
        )
        self.observer.start(timeout=timeout)

    def _stop_custom_entry_observer(self):
        if self.observer is None:
            raise ObserverNotStarted("Please first run 'start_custom_entry_observer'")
        self.observer.cancel()
        self.observer = None

    def _custom_entry_callback(self, event_pattern):
        log_info_to_console("Observer detected custom entry ({}): '{}'".format(get_timestamp(), event_pattern))
        self._custom_entry_occurred = True

    def verify_custom_entry_occurred(self, stop_after_failure=True):
        """
        Verify if custom entry was detected by observer. Remove observer after occurrence.
        :param stop_after_failure: if True, stop observer after failure
        """
        if self.observer is None:
            raise ObserverNotStarted("Please first run 'start_custom_entry_observer'")
        if not self._custom_entry_occurred:
            if stop_after_failure:
                self._stop_custom_entry_observer()
            raise CustomEntryNotDetected()

        self._stop_custom_entry_observer()
        self._custom_entry_occurred = False
